const VERSION = 'V10.5a-roadmap-selfcontained';
const stateName = '.v10_5a_roadmap_install_state.json';
const backupSuffix = '.antes-v10-5a-roadmap';

function findRoot(start) {
    let current = path.resolve(start);
    for (let i = 0; i < 6; i++) {
        if (fs.existsSync(path.join(current, 'package.json')) && fs.existsSync(path.join(current, 'packages'))) return current;
        const parent = path.dirname(current);
        if (parent === current) break;
        current = parent;
    }
    // Convenience: if installer is beside a single Kaetram folder, use it.
    try {
        const children = fs.readdirSync(start, { withFileTypes: true })
            .filter((e) => e.isDirectory())
            .map((e) => path.join(start, e.name))
            .filter((d) => fs.existsSync(path.join(d, 'package.json')) && fs.existsSync(path.join(d, 'packages')));
        if (children.length === 1) return children[0];
    } catch (_) {}
    return null;
}

const root = findRoot(__dirname);
if (!root) {
    console.error('\nERRO AO APLICAR V10.5a ROADMAP:');
    console.error('Nao encontrei a raiz do Kaetram. Coloque estes arquivos dentro de Kaetram-Open-develop (ou em uma subpasta dele) e execute novamente.');
    process.exit(1);
}

const p = (rel) => path.join(root, rel);
const statePath = p(stateName);
const hashBuffer = (buf) => crypto.createHash('sha256').update(buf).digest('hex');
const hashFile = (file) => fs.existsSync(file) ? hashBuffer(fs.readFileSync(file)) : null;

function preflight() {
    const kaykitPath = p('packages/client/src/ui/kaykit-character.ts');
    const vfxPath = p('packages/client/src/ui/combat-vfx.ts');
    const collisionPath = p('packages/server/data/map/cidade-inicial-collisions.json');
    if (!fs.existsSync(kaykitPath) || !fs.readFileSync(kaykitPath, 'utf8').includes('spinDirections'))
        throw new Error('Base V10.4 nao detectada: kaykit-character.ts sem a correcao de direcao/giro.');
    if (!fs.existsSync(vfxPath) || !fs.readFileSync(vfxPath, 'utf8').includes('kaetramWhirlA'))
        throw new Error('Base V10.4 nao detectada: combat-vfx.ts nao e o Steelstorm corrigido.');
    if (!fs.existsSync(collisionPath))
        throw new Error('Base V10.3/V10.4 nao detectada: arquivo de colisoes da cidade ausente.');
}

function decodeEntry(rel) {
    const entry = EMBEDDED[rel];
    if (!entry) throw new Error(`Arquivo embutido ausente: ${rel}`);
    const data = zlib.gunzipSync(Buffer.from(entry.gz, 'base64'));
    if (data.length !== entry.size) throw new Error(`Tamanho invalido no payload embutido: ${rel}`);
    const digest = hashBuffer(data);
    if (digest !== entry.sha256) throw new Error(`Integridade invalida no payload embutido: ${rel}`);
    return data;
}

function validate() {
    const itemsPath = p('packages/server/data/items.json');
    const items = JSON.parse(fs.readFileSync(itemsPath, 'utf8'));
    const arpgBases = Object.keys(items).filter((key) => key.startsWith('arpg_'));
    const uniques = Object.keys(items).filter((key) => key.startsWith('unique_'));
    if (arpgBases.length < 24) throw new Error(`Validacao falhou: esperado >=24 bases ARPG, encontrei ${arpgBases.length}.`);
    if (uniques.length < 3) throw new Error(`Validacao falhou: esperado >=3 Uniques, encontrei ${uniques.length}.`);

    const checks = [
        ['packages/server/src/game/arpg/items.ts', 'RARITY_LIMITS'],
        ['packages/server/src/game/arpg/items.ts', 'bestTierForItemLevel'],
        ['packages/server/src/game/arpg/mobs.ts', 'rollEliteProfile'],
        ['packages/server/src/game/entity/character/player/player.ts', 'toggleArpgSupport'],
        ['packages/server/src/game/entity/character/player/player.ts', 'setArpgLootFilter'],
        ['packages/server/src/game/entity/character/player/handler.ts', 'Auto-Sell'],
        ['packages/client/src/systems/smart-autofarm.ts', 'passesLootFilter'],
        ['packages/client/src/ui/warrior-skillbar.ts', 'SUPPORT_NAMES'],
        ['packages/client/src/game.ts', 'Idle / Farm — Loot Filter']
    ];
    for (const [rel, marker] of checks) {
        const file = p(rel);
        if (!fs.existsSync(file) || !fs.readFileSync(file, 'utf8').includes(marker))
            throw new Error(`Validacao falhou em ${rel}: marcador ${marker} ausente.`);
    }

    for (const key of [...arpgBases, ...uniques]) {
        const sprite = p(`packages/client/public/img/sprites/items/${key}.png`);
        if (!fs.existsSync(sprite)) throw new Error(`Sprite ausente: ${key}.png`);
    }
    return { arpgBases: arpgBases.length, uniques: uniques.length };
}

try {
    console.log(`Raiz detectada: ${root}`);
    console.log(`Payload autocontido: ${Object.keys(EMBEDDED).length} arquivos`);
    preflight();
    const files = Object.keys(EMBEDDED).sort();
    const protectedBefore = {
        world: hashFile(p('packages/server/data/map/world.json')),
        kaykit: hashFile(p('packages/client/src/ui/kaykit-character.ts')),
        vfx: hashFile(p('packages/client/src/ui/combat-vfx.ts'))
    };

    let state;
    if (fs.existsSync(statePath)) {
        state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
        if (state.version !== VERSION) throw new Error('Existe um estado de instalacao V10.5a incompatível. Use o rollback antes de tentar novamente.');
    } else {
        state = { version: VERSION, installedAt: new Date().toISOString(), root, files: {} };
        for (const rel of files) {
            const dst = p(rel);
            const existedBefore = fs.existsSync(dst);
            state.files[rel] = { existedBefore };
            if (existedBefore) {
                const backup = `${dst}${backupSuffix}`;
                if (!fs.existsSync(backup)) {
                    fs.mkdirSync(path.dirname(backup), { recursive: true });
                    fs.copyFileSync(dst, backup);
                }
            }
        }
        fs.writeFileSync(statePath, JSON.stringify(state, null, 2), 'utf8');
    }

    let written = 0;
    for (const rel of files) {
        const data = decodeEntry(rel);
        const dst = p(rel);
        fs.mkdirSync(path.dirname(dst), { recursive: true });
        fs.writeFileSync(dst, data);
        if (hashFile(dst) !== EMBEDDED[rel].sha256) throw new Error(`Falha ao verificar arquivo gravado: ${rel}`);
        written++;
        console.log(`[${written}/${files.length}] Atualizado: ${rel}`);
    }

    const result = validate();
    const protectedAfter = {
        world: hashFile(p('packages/server/data/map/world.json')),
        kaykit: hashFile(p('packages/client/src/ui/kaykit-character.ts')),
        vfx: hashFile(p('packages/client/src/ui/combat-vfx.ts'))
    };
    if (JSON.stringify(protectedBefore) !== JSON.stringify(protectedAfter))
        throw new Error('Protecao falhou: world/KayKit/Steelstorm mudou durante a instalacao. Use o rollback V10.5a.');

    for (const rel of ['packages/client/dist', 'packages/server/dist']) {
        const dir = p(rel);
        if (fs.existsSync(dir)) fs.rmSync(dir, { recursive: true, force: true });
    }

    console.log('\n=============================================');
    console.log(' V10.5a ROADMAP 1-7 APLICADO COM SUCESSO');
    console.log('=============================================');
    console.log(`Arquivos aplicados: ${files.length}`);
    console.log(`Bases ARPG: ${result.arpgBases} | Uniques: ${result.uniques}`);
    console.log('Cidade/KayKit/Steelstorm foram conferidos e NAO foram alterados.');
    console.log('Agora execute TESTAR-V10-5A-ROADMAP.cmd.');
    console.log('Depois rode: yarn build');
    console.log('Se terminar sem erro: yarn start');
} catch (error) {
    console.error('\nERRO AO APLICAR V10.5a ROADMAP:');
    console.error(error && error.stack ? error.stack : error);
    process.exit(1);
}
